+/// Shifts `a` right by `shift` bits, `1 <= shift <= 63`.
+#[inline(always)]
+fn shr_limbs(a: [u64; 4], shift: u32) -> [u64; 4] {
+    [
+        (a[0] >> shift) | (a[1] << (64 - shift)),
+        (a[1] >> shift) | (a[2] << (64 - shift)),
+        (a[2] >> shift) | (a[3] << (64 - shift)),
+        a[3] >> shift,
+    ]
+}
+
+/// Computes `a / 2^shift mod p` for `a < p` and `1 <= shift <= 63`.
+///
+/// Since `p = -1 mod 2^64`, adding `m * p` with `m = a mod 2^shift` clears the
+/// low `shift` bits; the quotient `(a + m * p) / 2^shift` is below `p`.
+#[inline(always)]
+fn div_pow2_mod(a: [u64; 4], shift: u32) -> [u64; 4] {
+    let m = a[0] & ((1u64 << shift) - 1);
+    let (w0, carry) = mac(a[0], m, MODULUS[0], 0);
+    let (w1, carry) = mac(a[1], m, MODULUS[1], carry);
+    let (w2, carry) = adc(a[2], 0, carry);
+    let (w3, w4) = mac(a[3], m, MODULUS[3], carry);
+    debug_assert_eq!(w0 & ((1u64 << shift) - 1), 0);
+
+    [
+        (w0 >> shift) | (w1 << (64 - shift)),
+        (w1 >> shift) | (w2 << (64 - shift)),
+        (w2 >> shift) | (w3 << (64 - shift)),
+        (w3 >> shift) | (w4 << (64 - shift)),
+    ]
+}
+
+/// Removes all factors of two from `u`, dividing `x` by the same power of two
+/// modulo p.
+#[inline(always)]
+fn strip_twos(u: &mut [u64; 4], x: &mut [u64; 4]) {
+    while is_even_limbs(*u) {
+        let shift = u[0].trailing_zeros().min(63);
+        *u = shr_limbs(*u, shift);
+        *x = div_pow2_mod(*x, shift);
+    }
+}

